def _k2a_reencode_scales(sf_u8:torch.Tensor):
 b=sf_u8.to(torch.int32)
 sign,ex,m=b>>7,(b>>3)&15,b&7
 nan=(ex==15)&(m==7)
 zero=(ex==0)&(m==0)
 sub=(ex==0)&(m!=0)
