def _vms_pack_words(cu):
 nu=cu.shape[0]
 x=cu.view(nu,2,8,8,8,4,4,2,2).permute(0,3,4,2,5,6,7,1,8).contiguous()
 x=x.view(nu,8,8,8,4,4,4,2).to(torch.int64)
